 class eventclass_profesores  extends eventsBase
{
	function __construct()
	{
	// fill list of events
		$this->events["BeforeAdd"]=true;

		$this->events["BeforeEdit"]=true;

		$this->events["BeforeDelete"]=true;

		$this->events["BeforeQueryList"]=true;


	}

//	handlers

		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record added
function BeforeAdd(&$values, &$message, $inline, &$pageObject)
{

		$usuario_id = intval($values["usuario_id"]);

if ($usuario_id <= 0) {
    $message = "Debe vincular una cuenta de usuario existente al docente.";
    return false;
}

$rsDoc = DB::Query("SELECT id FROM profesores WHERE usuario_id = " . $usuario_id . " LIMIT 1");
if ($rsDoc->fetchAssoc()) {
    $message = "El usuario seleccionado ya se encuentra registrado como docente.";
    return false;
}

if (empty($values["fecha_ingreso"])) {
    $values["fecha_ingreso"] = date("Y-m-d");
}

return true;
;		
} // function BeforeAdd

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record updated
function BeforeEdit(&$values, $where, &$oldvalues, &$keys, &$message, $inline, &$pageObject)
{

		$id_actual  = isset($keys["id"]) ? intval($keys["id"]) : 0;
$usuario_id = intval($values["usuario_id"]);

if ($usuario_id <= 0) {
    $message = "Debe vincular una cuenta de usuario válida.";
    return false;
}

$rsDoc = DB::Query("SELECT id FROM profesores WHERE usuario_id = " . $usuario_id . " AND id != " . $id_actual . " LIMIT 1");
if ($rsDoc->fetchAssoc()) {
    $message = "Este usuario ya se encuentra vinculado a otro docente.";
    return false;
}

return true;
;		
} // function BeforeEdit

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// Before record deleted
function BeforeDelete($where, &$deleted_values, &$message, &$pageObject)
{

		$prof_id = intval($deleted_values["id"]);

$rsCursos = DB::Query("SELECT COUNT(*) AS total FROM cursos WHERE profesor_id = " . $prof_id);
$rC = $rsCursos->fetchAssoc();
if (intval($rC["total"]) > 0) {
    $message = "No se puede eliminar el docente porque tiene cátedras asignadas. Reasigne sus cursos antes de eliminarlo.";
    return false;
}

return true;
;		
} // function BeforeDelete

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
				// List page: Before SQL query
function BeforeQueryList(&$strSQL, &$strWhereClause, &$strOrderBy, &$pageObject)
{

		// Docente: solo ve su propio registro de profesor
if ($_SESSION["rol"] == 'Docente') {
    $strWhereClause = whereAdd($strWhereClause, "id = " . intval($_SESSION["profesor_id"]));
}
;		
} // function BeforeQueryList

		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		
		



